using System.IO;
using System.Text.Json;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionCore;
using VisionPlugins.Calibration;
public static class NImageGeneratedBoardChecks {
 public static int Run(bool exportRotated=false){int checks=0;foreach(int generatorType in new[]{1,2,3,4}){
  int boardType=generatorType switch{1=>7,2=>6,3=>9,_=>8};var decoder=BitmapDecoder.Create(new Uri(Path.GetFullPath($"tests/NImageCalibration.PluginChecks/Fixtures/hik-generated-{generatorType}{(generatorType is 2 or 4?"-large":"")}.png")),BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);var gray=new FormatConvertedBitmap(decoder.Frames[0],PixelFormats.Gray8,null,0);var bytes=new byte[gray.PixelWidth*gray.PixelHeight];gray.CopyPixels(bytes,gray.PixelWidth,0);var image=new GrayImage(gray.PixelWidth,gray.PixelHeight,bytes);var board=NImageBoardRecognition.FindUpright(image,boardType)??throw new Exception($"No independently recognized generated board {boardType}");if(board.GridPitch!=10||board.Tags.Count<1)throw new Exception("Invalid official board identity");checks+=2;using(var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/n-image-calibration-generated-evidence.json"))){var native=evidence.RootElement.GetProperty("records").EnumerateArray().Single(r=>r.GetProperty("algorithmBoardType").GetInt32()==boardType).GetProperty("native");if(board.Points.Count!=native.GetProperty("pairs").GetInt32())throw new Exception($"Original generated board count differs: board={boardType}, actual={board.Points.Count}, native={native.GetProperty("pairs").GetInt32()}");checks++;var nativeOrder=native.GetProperty("corners").EnumerateArray().Select(row=>(X:row.GetProperty("world")[0].GetInt32(),Y:row.GetProperty("world")[1].GetInt32())).ToArray();if(!board.Points.Select(point=>(X:point.IndexX,Y:point.IndexY)).SequenceEqual(nativeOrder))throw new Exception($"Original generated board CornerPairs order differs: board={boardType}");checks++;double maximum=0;foreach(var point in board.Points){var expected=native.GetProperty("corners").EnumerateArray().Single(r=>r.GetProperty("world")[0].GetInt32()==point.IndexX&&r.GetProperty("world")[1].GetInt32()==point.IndexY).GetProperty("pixels")[0];double error=Math.Sqrt(Math.Pow(expected[0].GetDouble()-point.X,2)+Math.Pow(expected[1].GetDouble()-point.Y,2));maximum=Math.Max(maximum,error);if(error>1)throw new Exception($"Original generated board pixel differs: {boardType} {point} error={error}");checks++;}Console.WriteLine($"Generated board {boardType} original maximum pixel error {maximum:F6}");}
  if(generatorType==1){var projective=NImageBoardRecognition.FindProjective(image,boardType);Console.WriteLine($"Graph baseline: {projective?.Points.Count} points, {projective?.Tags.Count} tags");checks+=NImagePerspectiveChecks.Run(image,board,exportRotated);
   for(int turn=1;turn<4;turn++){var rotated=new byte[bytes.Length];for(int y=0;y<image.Height;y++)for(int x=0;x<image.Width;x++){int rx=turn switch{1=>image.Height-1-y,2=>image.Width-1-x,_=>y},ry=turn switch{1=>x,2=>image.Height-1-y,_=>image.Width-1-x};rotated[ry*image.Width+rx]=image[x,y];}var recovered=NImageBoardRecognition.FindOrthogonal(new GrayImage(image.Width,image.Height,rotated),boardType)??throw new Exception("Quarter-turn detection failed");if(recovered.Points.Count!=board.Points.Count)throw new Exception("Quarter-turn point count differs");checks++;foreach(var point in board.Points){var found=recovered.Points.Single(p=>p.IndexX==point.IndexX&&p.IndexY==point.IndexY);double ex=turn switch{1=>image.Height-1-point.Y,2=>image.Width-1-point.X,_=>point.Y},ey=turn switch{1=>point.X,2=>image.Height-1-point.Y,_=>image.Width-1-point.X};if(Math.Abs(found.X-ex)>.01||Math.Abs(found.Y-ey)>.01)throw new Exception("Quarter-turn coordinates differ");checks++;}}
   const int size=1400;double angle=7*Math.PI/180,c=Math.Cos(angle),s=Math.Sin(angle);var tilted=Enumerable.Repeat((byte)255,size*size).ToArray();for(int y=0;y<size;y++)for(int x=0;x<size;x++){double px=c*(x-699.5)+s*(y-699.5)+499.5,py=-s*(x-699.5)+c*(y-699.5)+499.5;int ix=(int)Math.Floor(px),iy=(int)Math.Floor(py);if(ix<0||iy<0||ix+1>=1000||iy+1>=1000)continue;double a=px-ix,b=py-iy;tilted[y*size+x]=(byte)Math.Round(image[ix,iy]*(1-a)*(1-b)+image[ix+1,iy]*a*(1-b)+image[ix,iy+1]*(1-a)*b+image[ix+1,iy+1]*a*b);}
   if(exportRotated){string folder=Path.GetFullPath("analysis/full-audit/n-image-calibration/rotated-generator");Directory.CreateDirectory(folder);for(int frame=0;frame<9;frame++){int dx=frame%3*10,dy=frame/3*10;var shifted=Enumerable.Repeat((byte)255,tilted.Length).ToArray();for(int y=0;y<size-dy;y++)tilted.AsSpan(y*size,size-dx).CopyTo(shifted.AsSpan((y+dy)*size+dx,size-dx));var bitmap=BitmapSource.Create(size,size,96,96,PixelFormats.Gray8,null,shifted,size);var encoder=new BmpBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(Path.Combine(folder,$"rotated-{frame}.bmp"));encoder.Save(output);}}
   var rotatedImage=new GrayImage(size,size,tilted);Console.WriteLine($"Rotation estimate {NImageRotatedBoardRecognition.EstimateAngle(rotatedImage)*180/Math.PI:F4} degrees");var tiltedBoard=NImageRotatedBoardRecognition.Find(rotatedImage,boardType)??throw new Exception("Seven-degree detection failed");Console.WriteLine($"Tilted board corners {tiltedBoard.Points.Count}, tags {tiltedBoard.Tags.Count}");checks++;using(var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/n-image-calibration-generated-evidence.json"))){var native=evidence.RootElement.GetProperty("rotated").GetProperty("native");if(tiltedBoard.Points.Count!=native.GetProperty("pairs").GetInt32())throw new Exception("Native rotated count differs");checks++;double maximum=0;foreach(var point in tiltedBoard.Points){var expected=native.GetProperty("corners").EnumerateArray().Single(r=>r.GetProperty("world")[0].GetInt32()==point.IndexX&&r.GetProperty("world")[1].GetInt32()==point.IndexY).GetProperty("pixels")[0];double error=Math.Sqrt(Math.Pow(point.X-expected[0].GetDouble(),2)+Math.Pow(point.Y-expected[1].GetDouble(),2));maximum=Math.Max(maximum,error);if(error>1)throw new Exception("Native rotated pixel differs");checks++;}Console.WriteLine($"Rotated original maximum pixel error {maximum:F6}");}
  }
  Console.WriteLine($"Official generated board {boardType}: {board.Points.Count} corners, {board.Tags.Count} decoded tags, pitch={board.GridPitch}");
 }return checks;}
}






